package ai.unifiedprocess.petclinic.vet.domain;

import org.jooq.DSLContext;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

import java.util.stream.Stream;

import static ai.unifiedprocess.demo.petclinic.database.tables.Specialties.SPECIALTIES;
import static ai.unifiedprocess.demo.petclinic.database.tables.VetSpecialties.VET_SPECIALTIES;
import static ai.unifiedprocess.demo.petclinic.database.tables.Vets.VETS;
import static org.jooq.Records.mapping;
import static org.jooq.impl.DSL.multiset;
import static org.jooq.impl.DSL.select;

/** Read queries for the veterinarian directory (UC-002). */
@Repository
@Transactional(readOnly = true)
public class VetRepository {

    private final DSLContext dsl;

    public VetRepository(DSLContext dsl) {
        this.dsl = dsl;
    }

    /** Fetches one bounded chunk with each veterinarian's specialties in name order. */
    public Stream<Vet> findPage(int offset, int limit) {
        return dsl.select(
                        VETS.ID,
                        VETS.FIRST_NAME,
                        VETS.LAST_NAME,
                        multiset(
                                select(SPECIALTIES.ID, SPECIALTIES.NAME)
                                        .from(VET_SPECIALTIES)
                                        .join(SPECIALTIES)
                                        .on(SPECIALTIES.ID.eq(VET_SPECIALTIES.SPECIALTY_ID))
                                        .where(VET_SPECIALTIES.VET_ID.eq(VETS.ID))
                                        .orderBy(SPECIALTIES.NAME.asc(), SPECIALTIES.ID.asc()))
                                .convertFrom(result -> result.map(mapping(Specialty::new))))
                .from(VETS)
                .orderBy(VETS.LAST_NAME.asc(), VETS.FIRST_NAME.asc(), VETS.ID.asc())
                .offset(offset)
                .limit(limit)
                .fetch(mapping(Vet::new))
                .stream();
    }

    /** Returns the number of veterinarians available to the lazy grid. */
    public int count() {
        return dsl.fetchCount(VETS);
    }
}
