+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridVariant;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.theme.lumo.LumoUtility;
+
+import java.util.stream.Collectors;
+
+/** UC-002: browse veterinarians and their specialties with an incrementally loaded grid. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VeterinariansView extends VerticalLayout {
+
+    private transient VetRepository vetRepository;
+
+    public VeterinariansView(VetRepository vetRepository) {
+        this.vetRepository = vetRepository;
+
+        setSizeFull();
+        setPadding(true);
+        setSpacing(false);
+
+        H2 heading = new H2("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE, LumoUtility.FontSize.XXLARGE);
+
+        Paragraph introduction = new Paragraph(
+                "Meet the veterinarians caring for your pets and browse their specialties.");
+        introduction.addClassNames(
+                LumoUtility.TextColor.SECONDARY,
+                LumoUtility.Margin.Top.SMALL,
+                LumoUtility.Margin.Bottom.LARGE);
+
+        Grid<Vet> grid = createGrid();
+        add(heading, introduction, grid);
+        setFlexGrow(1, grid);
+    }
+
+    private Grid<Vet> createGrid() {
+        Grid<Vet> grid = new Grid<>();
+        grid.setSizeFull();
+        grid.setAriaLabel("Veterinarians and their specialties");
+        grid.setEmptyStateText("No veterinarians are currently listed.");
+        grid.addThemeVariants(GridVariant.NO_BORDER, GridVariant.LUMO_ROW_STRIPES);
+
+        grid.addColumn(Vet::firstName).setHeader("First name").setAutoWidth(true);
+        grid.addColumn(Vet::lastName).setHeader("Last name").setAutoWidth(true);
+        grid.addColumn(vet -> specialtiesText(vet))
+                .setHeader("Specialties")
+                .setFlexGrow(1);
+
+        grid.setItems(
+                query -> vetRepository.findPage(query.getOffset(), query.getLimit()),
+                query -> vetRepository.count());
+        return grid;
+    }
+
+    private static String specialtiesText(Vet vet) {
+        if (vet.specialties().isEmpty()) {
+            return "none";
+        }
+        return vet.specialties().stream()
+                .map(Specialty::name)
+                .collect(Collectors.joining(", "));
+    }
+}
